function saveBlob(data: BlobPart, filename: string, type = 'text/plain') { const url = URL.createObjectURL(new Blob([data], { type })); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url) }
function formatDate(date: string) { return date ? new Date(`${date}T00:00:00`).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }) : '待填写' }
function demoFields(id: string, profile: Profile): Record<string, string> { const base = { name: profile.name }; if (id === 'passport') return { ...base, passportNo: 'L12345678', passportExpiry: '2027-05-01' }; if (id === 'insurance') return { ...base, insuranceStart: profile.startDate, insuranceEnd: '2026-08-08', coverage: '€30,000' }; if (id === 'residence') return { ...base, permitExpiry: profile.residencePermitExpiry }; if (id === 'student') return { ...base, school: profile.schoolOrEmployer, issueDate: '2026-07-01' }; if (id === 'transport') return { ...base, outboundDate: profile.startDate, returnDate: profile.endDate }; if (id === 'hotel') return { hotelCity: 'Paris', checkin: profile.startDate, checkout: '2026-08-04' }; return base }

function Landing() { const navigate = useNavigate(); const { dispatch } = useStore(); const start = () => { dispatch({ type: 'RESET' }); navigate('/setup') }; const demo = () => { dispatch({ type: 'RESET' }); dispatch({ type: 'SET_PROFILE', profile: demoProfile }); ['passport', 'application', 'transport', 'hotel', 'insurance', 'funds', 'itinerary', 'cover', 'residence', 'student'].forEach((id) => dispatch({ type: 'SET_STATUS', id, status: id === 'insurance' ? 'uploaded' : 'checked' })); dispatch({ type: 'SET_EXTRACTED', id: 'insurance', fields: demoFields('insurance', demoProfile) }); dispatch({ type: 'SET_EXTRACTED', id: 'passport', fields: demoFields('passport', demoProfile) }); dispatch({ type: 'SET_EXTRACTED', id: 'transport', fields: demoFields('transport', demoProfile) }); dispatch({ type: 'SET_EXTRACTED', id: 'residence', fields: demoFields('residence', demoProfile) }); dispatch({ type: 'SET_EXTRACTED', id: 'student', fields: demoFields('student', demoProfile) }); dispatch({ type: 'SET_EXTRACTED', id: 'hotel', fields: { hotelCity: 'Rome', checkin: '2026-08-04', checkout: '2026-08-09' } }); dispatch({ type: 'SET_EXTRACTED', id: 'funds', fields: { name: demoProfile.name, bankDate: '2026-07-20', balance: 'GBP 5,400' } }); dispatch({ type: 'SET_ITINERARY', itinerary: demoItinerary }); dispatch({ type: 'SET_LETTER', coverLetter: demoCoverLetter }); navigate('/workspace/overview') }
  return <div className="landing"><div className="container"><header className="topbar"><div className="brand"><span className="brand-mark"><PlaneIcon /></span>签里行间</div><button className="btn btn-secondary" onClick={demo}>查看示例申请</button></header><section className="hero"><div><div className="eyebrow">Visa preparation workspace</div><h1>把复杂的申根签材料，<span>一次理清。</span></h1><p>从主申国选择、官方Checklist，到行程单、解释信和跨材料一致性检查，帮你把每一步准备得更清楚、更可信。</p><div className="actions"><button className="btn btn-primary" onClick={start}>开始准备申请 <ArrowRight size={17}/></button><button className="btn btn-secondary" onClick={demo}>体验冲突案例</button></div></div><div className="hero-card"><div className="section-title"><div><small>当前申请进度</small><h3>法国 · 英国留学生</h3></div><span className="badge yellow">3 个待确认</span></div><div className="mini-progress"><span /></div><div className="grid-2" style={{ marginTop: 18 }}><div className="stat"><strong>24</strong><span>材料项目</span></div><div className="stat"><strong>92%</strong><span>信息完整度</span></div></div><div className="notice blue" style={{ marginTop: 16 }}><ShieldCheck size={17}/><span>检查依据来自官方要求；社区经验仅用于路线灵感。</span></div></div></section><div className="feature-grid"><Feature icon={<ShieldCheck/>} title="官方依据清单" text="按主申国、递签地和申请身份生成材料清单，区分线上提交与现场携带。"/><Feature icon={<FileCheck2/>} title="跨材料一致性体检" text="发现日期、城市、酒店、保险和解释信之间的矛盾，给出可修复建议。"/><Feature icon={<Sparkles/>} title="文书一键生成" text="保留真实机酒搜索工作流，生成可编辑的中英双语行程单与解释信。"/></div></div></div> }
function PlaneIcon() { return <Globe2 size={19}/> }
function Feature({ icon, title, text }: { icon: ReactNode; title: string; text: string }) { return <div className="feature">{icon}<h3>{title}</h3><p>{text}</p></div> }

function Setup() { const { dispatch } = useStore(); const navigate = useNavigate(); const [step, setStep] = useState(1); const [profile, setProfile] = useState<Profile>(defaultProfile); const update = (key: keyof Profile, value: unknown) => setProfile((p) => ({ ...p, [key]: value })); const canNext = step === 1 ? !!profile.residenceCity : step === 2 ? !!profile.departureCity && !!profile.startDate && !!profile.endDate : !!profile.name
  const submit = () => { dispatch({ type: 'SET_PROFILE', profile }); navigate('/workspace/overview') }
  return <div className="landing"><div className="container" style={{ maxWidth: 850 }}><header className="topbar"><Link to="/" className="brand" style={{ textDecoration: 'none' }}><span className="brand-mark"><PlaneIcon /></span>签里行间</Link><span className="muted">建立一次申请档案</span></header><div className="card" style={{ marginTop: 38, padding: 30 }}><div className="stepper"><span className="step-dot done"/><span className={`step-dot ${step >= 2 ? 'done' : 'active'}`}/><span className={`step-dot ${step >= 3 ? 'done' : ''}`}/></div><div className="page-head"><div><div className="eyebrow">Step {step} of 3</div><h1>{step === 1 ? '先确认你的递签环境' : step === 2 ? '再填写旅行计划' : '最后确认申请人信息'}</h1><p>{step === 1 ? '材料要求会根据递签地和身份变化。' : step === 2 ? '不用一次填完，之后都可以回到申请总览修改。' : '这些信息会用于清单、行程单和解释信。'}</p></div></div>{step === 1 && <div className="form-grid"><div className="form-field full"><span className="label">从哪里递交？</span><div className="choice-row"><button className={`choice ${profile.submissionPlace === 'china' ? 'selected' : ''}`} onClick={() => update('submissionPlace', 'china')}>中国大陆</button><button className={`choice ${profile.submissionPlace === 'uk' ? 'selected' : ''}`} onClick={() => { update('submissionPlace', 'uk'); update('status', 'student') }}>英国（中国留学生）</button></div></div><div><label className="label">当前身份</label><select className="field" value={profile.status} onChange={(e) => update('status', e.target.value as ApplicantStatus)}><option value="employed">在职</option><option value="student">学生</option><option value="self_employed">自由职业</option><option value="unemployed">无固定工作</option></select></div><div><label className="label">居住城市</label><input className="field" value={profile.residenceCity} placeholder="例如：上海 / London" onChange={(e) => update('residenceCity', e.target.value)}/></div>{profile.submissionPlace === 'uk' && <><div><label className="label">居留类型</label><input className="field" value={profile.residencePermitType} placeholder="UK Student eVisa" onChange={(e) => update('residencePermitType', e.target.value)}/></div><div><label className="label">居留有效期</label><input className="field" type="date" value={profile.residencePermitExpiry} onChange={(e) => update('residencePermitExpiry', e.target.value)}/></div></>}</div>}{step === 2 && <div className="form-grid"><div><label className="label">主申国家</label><select className="field" value={profile.applicationCountry} onChange={(e) => update('applicationCountry', e.target.value)}>{countries.map((c) => <option key={c} value={c}>{countryLabels[c]} {c}</option>)}</select></div><div><label className="label">首入境国家</label><select className="field" value={profile.entryCountry} onChange={(e) => update('entryCountry', e.target.value)}>{countries.map((c) => <option key={c} value={c}>{countryLabels[c]}</option>)}</select></div><div><label className="label">出发城市</label><input className="field" value={profile.departureCity} placeholder="London" onChange={(e) => update('departureCity', e.target.value)}/></div><div><label className="label">返回城市</label><input className="field" value={profile.returnCity} placeholder="London" onChange={(e) => update('returnCity', e.target.value)}/></div><div><label className="label">出发日期</label><input className="field" type="date" value={profile.startDate} onChange={(e) => update('startDate', e.target.value)}/></div><div><label className="label">返回日期</label><input className="field" type="date" value={profile.endDate} onChange={(e) => update('endDate', e.target.value)}/></div><div className="form-field full"><label className="label">目的地国家（可多选）</label><div className="choice-row">{countries.map((c) => <button key={c} className={`choice ${profile.destinationCountries.includes(c) ? 'selected' : ''}`} onClick={() => update('destinationCountries', profile.destinationCountries.includes(c) ? profile.destinationCountries.filter((x) => x !== c) : [...profile.destinationCountries, c])}>{countryLabels[c]}</button>)}</div></div></div>}{step === 3 && <div className="form-grid"><div className="form-field full"><label className="label">姓名（与护照一致）</label><input className="field" value={profile.name} placeholder="例如：Lina Chen" onChange={(e) => update('name', e.target.value)}/></div><div><label className="label">学校／雇主</label><input className="field" value={profile.schoolOrEmployer} onChange={(e) => update('schoolOrEmployer', e.target.value)}/></div><div><label className="label">资金来源</label><input className="field" value={profile.fundingSource} placeholder="Personal savings" onChange={(e) => update('fundingSource', e.target.value)}/></div><div><label className="label">返程理由</label><input className="field" value={profile.returnReason} placeholder="Return to university / work" onChange={(e) => update('returnReason', e.target.value)}/></div><div><label className="label">同行人</label><input className="field" value={profile.companions} placeholder="可选" onChange={(e) => update('companions', e.target.value)}/></div><div className="form-field full"><div className="notice blue"><Info size={17}/><span>你选择的主申国是{countryLabels[profile.applicationCountry]}。多国行程应向主要目的地或最长停留国申请；最终请以官方要求为准。</span></div></div></div>}<div className="modal-actions"><Link className="btn btn-secondary" to="/">取消</Link>{step > 1 && <button className="btn btn-secondary" onClick={() => setStep(step - 1)}><ArrowLeft size={16}/>上一步</button>}{step < 3 ? <button className="btn btn-primary" disabled={!canNext} onClick={() => setStep(step + 1)}>下一步 <ArrowRight size={16}/></button> : <button className="btn btn-primary" disabled={!canNext} onClick={submit}>创建申请 <Check size={16}/></button>}</div></div></div></div> }

function Shell() { const { state, dispatch } = useStore(); const navigate = useNavigate(); const [mobile, setMobile] = useState(false); if (!state.profile) return <Navigate to="/setup" replace />; const required = requirementsFor(state.profile).filter((r) => r.level === 'required'); const completed = required.filter((r) => ['checked', 'uploaded', 'done'].includes(state.statuses[r.id])).length; const progress = Math.min(100, Math.round((completed / Math.max(required.length, 1)) * 100)); return <div className="workspace"><aside className="sidebar"><Link to="/workspace/overview" className="brand" style={{ textDecoration: 'none' }}><span className="brand-mark"><PlaneIcon /></span>签里行间</Link><div className="case-chip"><strong>{countryLabels[state.profile.applicationCountry]} · {state.profile.submissionPlace === 'uk' ? '英国递签' : '中国大陆递签'}</strong><span>{state.profile.name || '未填写姓名'} · {formatDate(state.profile.startDate)}—{formatDate(state.profile.endDate)}</span></div><nav className="nav">{navItems.map(({ to, label, icon: Icon }) => <NavLink key={to} to={to} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><Icon size={17}/>{label}</NavLink>)}</nav><div className="sidebar-bottom"><div className="progress-label"><span>材料完成度</span><strong>{progress}%</strong></div><div className="mini-progress"><span style={{ width: `${progress}%` }}/></div><button className="btn btn-ghost" style={{ width: '100%', marginTop: 12 }} onClick={() => { if (confirm('清除当前申请数据？')) { dispatch({ type: 'RESET' }); navigate('/') } }}><Trash2 size={15}/>清除本地申请</button></div></aside><main className="main"><div className="main-inner"><button className="btn btn-ghost mobile-menu" onClick={() => setMobile(!mobile)}><Menu size={17}/>导航</button><Outlet /></div></main></div> }

function PageHead({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) {
  const { dispatch } = useStore()
  const navigate = useNavigate()
  const startNew = () => {
    if (confirm('新建申请会清空当前申请信息，是否继续？')) {
      dispatch({ type: 'RESET' })
      navigate('/setup')
    }
  }
  return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description && <p>{description}</p>}</div><div className="head-actions"><Link className="btn btn-secondary" to="/"><Home size={16}/>返回首页</Link><button className="btn btn-secondary" onClick={startNew}><Plus size={16}/>新建申请</button>{actions}</div></div>
}
function Overview() { const { state } = useStore(); const p = state.profile!; const reqs = requirementsFor(p); const completed = reqs.filter((r) => ['checked', 'uploaded', 'done'].includes(state.statuses[r.id])).length; const issues = state.report?.issues.filter((i) => i.severity === 'error').length || 0; const cards = [{ to: '/workspace/materials', icon: ClipboardCheck, title: '准备材料', text: `${completed}/${reqs.length} 项已确认`, tone: completed === reqs.length ? 'green' : 'yellow' }, { to: '/workspace/itinerary', icon: Globe2, title: '生成行程单', text: state.itinerary.generated ? '已生成，可编辑' : '填写城市与停留日期', tone: state.itinerary.generated ? 'green' : 'gray' }, { to: '/workspace/cover-letter', icon: FileText, title: '生成解释信', text: state.coverLetter.generated ? '已生成，可编辑' : '补充资金与返程理由', tone: state.coverLetter.generated ? 'green' : 'gray' }, { to: '/workspace/consistency', icon: ShieldCheck, title: '一致性检查', text: state.report ? `${issues} 个必须修复` : '尚未检查', tone: issues ? 'red' : 'gray' }, { to: '/workspace/package', icon: PackageCheck, title: '导出材料包', text: '按递交渠道整理', tone: 'gray' }]; return <><PageHead eyebrow="Application workspace" title="申请总览" description="所有准备工作都在这里串起来，先完成必需材料，再做一次一致性体检。" actions={<Link className="btn btn-primary" to="/workspace/consistency"><ShieldCheck size={16}/>检查全部材料</Link>}/><div className="grid-4"><div className="stat"><strong>{completed}</strong><span>已确认材料</span></div><div className="stat"><strong>{reqs.length - completed}</strong><span>待处理材料</span></div><div className="stat"><strong>{state.documents.length}</strong><span>本次上传文件</span></div><div className="stat"><strong>{issues}</strong><span>必须修复问题</span></div></div><div className="section card"><div className="section-title"><h2>当前申请</h2><span className="badge blue">官方来源：{officialSources[p.applicationCountry]?.name}</span></div><div className="grid-3"><div><span className="label">主申国家</span><strong>{countryLabels[p.applicationCountry]} {p.applicationCountry}</strong></div><div><span className="label">递签地</span><strong>{p.submissionPlace === 'uk' ? '英国' : '中国大陆'}</strong></div><div><span className="label">旅行时间</span><strong>{formatDate(p.startDate)}—{formatDate(p.endDate)}</strong></div></div><div className="notice blue" style={{ marginTop: 17 }}><Info size={16}/><span>官方来源最后核验：{officialSources[p.applicationCountry]?.checked}。社区经验仅作路线灵感，不替代官方要求。</span></div></div><div className="section-title section"><h2>准备步骤</h2><span className="muted">建议从上到下完成</span></div><div className="grid-2">{cards.map(({ to, icon: Icon, title, text, tone }) => <Link className="card" to={to} key={to} style={{ textDecoration: 'none', display: 'flex', gap: 15, alignItems: 'center' }}><span className={`badge ${tone}`} style={{ width: 40, height: 40, justifyContent: 'center', borderRadius: 13 }}><Icon size={20}/></span><span style={{ flex: 1 }}><strong>{title}</strong><small className="muted" style={{ display: 'block', marginTop: 5 }}>{text}</small></span><ChevronRight size={17} color="#9b928d"/></Link>)}</div><div className="footer-note">本产品只帮助整理和检查材料，不保证签证结果。最终以使领馆及签证中心的最新要求为准。</div></> }

function Materials() { const { state, dispatch } = useStore(); const profile = state.profile!; const requirements = requirementsFor(profile); const [filter, setFilter] = useState('全部'); const [drawer, setDrawer] = useState<Requirement | null>(null); const [postUrl, setPostUrl] = useState(''); const [postNote, setPostNote] = useState(''); const source = officialSources[profile.applicationCountry] || officialSources.France; const categories = [...new Set(requirements.map((r) => r.category))]; const matches = (r: Requirement) => filter === '全部' || filter === r.channel || filter === r.level || filter === statusLabel[state.statuses[r.id] || 'todo']; const upload = (r: Requirement, file?: File) => { if (!file) return; dispatch({ type: 'ADD_DOCUMENT', document: { id: `${r.id}-${Date.now()}`, requirementId: r.id, name: file.name, size: file.size, type: file.type } }); dispatch({ type: 'SET_EXTRACTED', id: r.id, fields: demoFields(r.id, profile) }) }; const addPost = () => { if (!postUrl.trim()) return; dispatch({ type: 'ADD_POST', post: { id: `custom-${Date.now()}`, title: postNote || '我的小红书路线参考', tags: ['用户添加', '路线灵感'], summary: '用户添加的路线链接，可作为本次行程参考。', url: postUrl } }); setPostUrl(''); setPostNote('') }; return <><PageHead eyebrow="Step 2 · Materials" title="材料清单" description="按你的主申国、递签地和身份生成。每项都标注递交渠道和官方依据。" actions={<Link className="btn btn-primary" to="/workspace/itinerary">下一步：行程单 <ArrowRight size={16}/></Link>}/><div className="source-card"><div><strong>{countryLabels[profile.applicationCountry]}官方来源：{source.name}</strong><div className="muted" style={{ fontSize: 12, marginTop: 5 }}>最后核验：{source.checked} · {profile.submissionPlace === 'uk' ? '英国递签' : '中国大陆递签'}</div></div><a href={source.url} target="_blank" rel="noreferrer">打开官方页面 <ArrowRight size={14}/></a></div><div className="notice blue section"><Info size={17}/><span>“官方要求”决定材料是否需要准备；“社区经验”只用于路线和准备技巧参考，不参与合规判断。</span></div><div className="section-title section"><h2>我的材料 <span className="muted" style={{ fontSize: 13 }}>{requirements.filter((r) => ['checked', 'uploaded', 'done'].includes(state.statuses[r.id])).length}/{requirements.length}</span></h2><div className="filter-row" style={{ margin: 0 }}>{['全部', 'required', 'online', 'onsite', 'both', '未开始', '需要修改'].map((x) => <button key={x} className={`filter ${filter === x ? 'active' : ''}`} onClick={() => setFilter(x)}>{x === 'required' ? '必需' : x === 'online' ? '线上提交' : x === 'onsite' ? '现场携带' : x === 'both' ? '两者都要' : x}</button>)}</div></div>{categories.map((category) => { const items = requirements.filter((r) => r.category === category && matches(r)); if (!items.length) return null; return <section className="section" key={category}><h3 className="group-title">{category}</h3><div className="grid-2">{items.map((r) => { const status = state.statuses[r.id] || 'todo'; const doc = state.documents.find((d) => d.requirementId === r.id); return <div className="card material-card" key={r.id}><div><h3>{r.name}</h3><p>{r.en}</p><div className="material-meta"><span className={`badge ${r.level === 'required' ? 'red' : 'gray'}`}>{r.level === 'required' ? '必需' : r.level === 'conditional' ? '条件必需' : '建议'}</span><span className="badge blue">{channelLabel[r.channel]}</span><span className={`badge ${status === 'uploaded' ? 'green' : status === 'todo' ? 'gray' : 'yellow'}`}>{statusLabel[status]}</span></div><p style={{ marginTop: 9 }}>{r.originals} · {r.applies}</p>{doc && <p style={{ color: 'var(--green)', marginTop: 6 }}><FileCheck2 size={13} style={{ verticalAlign: 'middle' }}/> {doc.name}</p>}</div><div className="material-actions"><label className="small-btn primary"><Upload size={13}/>上传<input type="file" accept=".pdf,.png,.jpg,.jpeg" hidden onChange={(e) => upload(r, e.target.files?.[0])}/></label><button className="small-btn" onClick={() => dispatch({ type: 'SET_STATUS', id: r.id, status: status === 'checked' ? 'todo' : 'checked' })}><Check size={13}/>打勾</button><button className="small-btn" onClick={() => setDrawer(r)}>详情</button></div></div>})}</div></section>})}<section className="section"><div className="section-title"><div><h2>小红书路线灵感</h2><p className="muted">仅用于生成行程参考，不作为官方材料依据。</p></div><BookOpen size={20} color="var(--coral)"/></div><div className="grid-3">{state.posts.map((post) => <div className="post-card" key={post.id}><h3>{post.title}</h3><div>{post.tags.map((tag) => <span className="tag" key={tag}>{tag}</span>)}</div><p>{post.summary}</p><button className={`small-btn ${state.itinerary.selectedPosts.includes(post.id) ? 'primary' : ''}`} onClick={() => dispatch({ type: 'TOGGLE_POST', id: post.id })}>{state.itinerary.selectedPosts.includes(post.id) ? '已加入行程参考' : '加入行程参考'}</button>{post.url && <a href={post.url} target="_blank" rel="noreferrer" className="muted" style={{ display: 'block', fontSize: 12, marginTop: 9 }}>查看原链接</a>}</div>)}</div><div className="card" style={{ marginTop: 15 }}><div className="form-grid"><div><label className="label">粘贴小红书链接</label><input className="field" value={postUrl} onChange={(e) => setPostUrl(e.target.value)} placeholder="https://www.xiaohongshu.com/..."/></div><div><label className="label">你想参考的路线／关键词</label><input className="field" value={postNote} onChange={(e) => setPostNote(e.target.value)} placeholder="例如：法意火车、博物馆路线"/></div></div><button className="btn btn-secondary" style={{ marginTop: 13 }} onClick={addPost}><Plus size={16}/>加入我的参考</button></div></section>{drawer && <MaterialDrawer requirement={drawer} state={state} onClose={() => setDrawer(null)} dispatch={dispatch}/>}</> }
function MaterialDrawer({ requirement, state, onClose, dispatch }: { requirement: Requirement; state: ReturnType<typeof useStore>['state']; onClose: () => void; dispatch: ReturnType<typeof useStore>['dispatch'] }) { const fields = state.extracted[requirement.id] || {}; const [local, setLocal] = useState(fields); return <div className="drawer"><div className="drawer-panel"><div className="drawer-head"><div><div className="eyebrow">Material detail</div><h2 style={{ margin: '4px 0' }}>{requirement.name}</h2></div><button className="icon-btn" onClick={onClose}><X size={17}/></button></div><div className="notice blue"><CloudUpload size={16}/><span>请核对并确认下方识别字段。</span></div><div className="section"><span className="label">递交方式</span><span className="badge blue">{channelLabel[requirement.channel]}</span></div><div className="section"><span className="label">官方依据</span><div className="source-card"><span>{requirement.source}</span><a href={requirement.sourceUrl} target="_blank" rel="noreferrer">打开</a></div></div>{requirement.fields.length > 0 && <div className="section"><span className="label">识别字段</span>{requirement.fields.map((key) => <div key={key} style={{ marginBottom: 12 }}><label className="label">{key}</label><input className="field" value={local[key] || ''} onChange={(e) => setLocal({ ...local, [key]: e.target.value })}/></div>)}<button className="btn btn-primary" onClick={() => { dispatch({ type: 'SET_EXTRACTED', id: requirement.id, fields: local }); dispatch({ type: 'SET_STATUS', id: requirement.id, status: 'done' }); onClose() }}><Check size={16}/>保存并确认字段</button></div>}<div className="modal-actions"><button className="btn btn-secondary" onClick={onClose}>关闭</button></div></div></div> }

function Itinerary() { const { state, dispatch } = useStore(); const p = state.profile!; const initial = state.itinerary.cities.length ? state.itinerary.cities : [{ id: 'stay-1', city: '', country: p.applicationCountry, checkin: p.startDate, checkout: p.endDate, hotel: '' }]; const [cities, setCities] = useState<CityStay[]>(initial); const [notes, setNotes] = useState(state.itinerary.notes); const [loading, setLoading] = useState(false); const update = (id: string, key: keyof CityStay, value: string) => setCities((all) => all.map((c) => c.id === id ? { ...c, [key]: value } : c)); const generate = () => { setLoading(true); const next = { ...state.itinerary, cities, notes, days: [], generated: false }; setTimeout(() => { const days = generateDays({ ...state, itinerary: next }); dispatch({ type: 'SET_ITINERARY', itinerary: { ...next, days, generated: true } }); setLoading(false) }, 650) }; return <><PageHead eyebrow="Step 3 · Itinerary" title="生成行程单" description="行程要真实、连贯、能与住宿和交通材料互相支持。小红书路线只是可选灵感。" actions={<Link className="btn btn-primary" to="/workspace/cover-letter">下一步：解释信 <ArrowRight size={16}/></Link>}/><div className="notice blue"><ShieldCheck size={17}/><span>生成前会检查主申国、城市归属、停留晚数和住宿覆盖；不替你虚构真实旅行事实。</span></div><div className="card section"><div className="section-title"><h2>城市与住宿</h2><button className="small-btn primary" onClick={() => setCities([...cities, { id: `stay-${Date.now()}`, city: '', country: p.applicationCountry, checkin: '', checkout: '', hotel: '' }])}><Plus size={14}/>添加城市</button></div>{cities.map((stay, index) => <div className="city-row" key={stay.id}><div><label className="label">城市 {index + 1}</label><input className="field" value={stay.city} placeholder="Paris" onChange={(e) => update(stay.id, 'city', e.target.value)}/></div><div><label className="label">国家</label><select className="field" value={stay.country} onChange={(e) => update(stay.id, 'country', e.target.value)}>{countries.map((c) => <option key={c}>{c}</option>)}</select></div><div><label className="label">入住</label><input className="field" type="date" value={stay.checkin} onChange={(e) => update(stay.id, 'checkin', e.target.value)}/></div><div><label className="label">离店</label><input className="field" type="date" value={stay.checkout} onChange={(e) => update(stay.id, 'checkout', e.target.value)}/></div><div><label className="label">住宿</label><input className="field hotel" value={stay.hotel} placeholder="酒店名称" onChange={(e) => update(stay.id, 'hotel', e.target.value)}/></div>{cities.length > 1 && <button className="icon-btn" onClick={() => setCities(cities.filter((c) => c.id !== stay.id))}><Trash2 size={15}/></button>}</div>)}<label className="label">行程补充说明</label><textarea className="field" rows={3} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="旅行目的、活动偏好或需要解释的情况"/><div className="modal-actions"><button className="btn btn-primary" onClick={generate} disabled={loading}>{loading ? <><RefreshCw size={16} className="spin"/>正在生成…</> : <><Sparkles size={16}/>生成双语行程单</>}</button></div></div>{state.itinerary.generated && <ItineraryResult state={state}/>}<div className="section"><div className="section-title"><h2>参考过的路线灵感</h2><Link to="/workspace/materials" className="muted">去添加帖子</Link></div><div className="grid-3">{state.posts.filter((post) => state.itinerary.selectedPosts.includes(post.id)).map((post) => <div className="post-card" key={post.id}><h3>{post.title}</h3><p>{post.summary}</p><span className="badge gray">社区经验，仅作参考</span></div>)}{!state.itinerary.selectedPosts.length && <div className="card empty" style={{ gridColumn: '1/-1' }}>尚未选择小红书路线，行程仍可正常生成。</div>}</div></div></> }
function ItineraryResult({ state }: { state: ReturnType<typeof useStore>['state'] }) { const days = state.itinerary.days; const exportItinerary = () => { const csv = ['日期,城市,交通,住宿,中文活动,English activity', ...days.map((d) => [d.date, d.city, d.transport, d.hotel, d.activityZh, d.activityEn].map((x) => `"${x.replaceAll('"', '""')}"`).join(','))].join('\n'); saveBlob('\ufeff' + csv, 'Visa_Itinerary.csv', 'text/csv;charset=utf-8') }; return <div className="card section"><div className="section-title"><div><h2>行程预览</h2><span className="muted">机酒建议 · 可编辑</span></div><button className="small-btn" onClick={exportItinerary}><Download size={14}/>导出Excel兼容CSV</button></div><div className="timeline">{days.map((day, i) => <div className="day-card" key={`${day.date}-${i}`}><div className="day-date">Day {i + 1}<br/><span>{formatDate(day.date)}</span></div><div><h3>{day.city}</h3><p><strong>交通：</strong>{day.transport}</p><p><strong>住宿：</strong>{day.hotel}</p><p>· {day.activityZh}</p><p className="muted">{day.activityEn}</p></div></div>)}</div><div className="grid-2" style={{ marginTop: 17 }}><div className="notice blue"><Globe2 size={15}/><span>机票候选：{state.profile?.departureCity || '出发地'} → {days[0]?.city || '首站'} · <a href="https://www.google.com/travel/flights" target="_blank" rel="noreferrer">打开 Google Flights</a></span></div><div className="notice blue"><Home size={15}/><span>酒店候选：按城市检索 · <a href="https://www.booking.com/" target="_blank" rel="noreferrer">打开 Booking</a></span></div></div></div> }

function CoverLetterPage() { const { state, dispatch } = useStore(); const p = state.profile!; const [style, setStyle] = useState<CoverLetter['style']>(state.coverLetter.style); const [emphasis, setEmphasis] = useState<string[]>(state.coverLetter.emphasis); const [special, setSpecial] = useState(state.coverLetter.special); const [loading, setLoading] = useState(false); const [lang, setLang] = useState<'zh' | 'en'>('en'); const options = ['财力能力', '学业约束', '工作约束', '返程意图', '旅行历史']; const generate = () => { setLoading(true); setTimeout(() => { dispatch({ type: 'SET_LETTER', coverLetter: generateLetter(state, style, emphasis, special) }); setLoading(false) }, 500) }; const updateText = (value: string) => dispatch({ type: 'SET_LETTER', coverLetter: { ...state.coverLetter, [lang]: value } }); const download = () => saveBlob(state.coverLetter.en + '\n\n--- 中文版本 ---\n\n' + state.coverLetter.zh, `Cover_Letter_${p.applicationCountry}.doc`, 'application/msword'); return <><PageHead eyebrow="Step 4 · Cover letter" title="生成解释信" description="自动读取申请档案与最终行程，生成可编辑的中英双语说明。" actions={<Link className="btn btn-primary" to="/workspace/consistency">下一步：一致性检查 <ArrowRight size={16}/></Link>}/><div className="grid-2"><div className="card"><h2 style={{ fontSize: 18 }}>生成设置</h2><label className="label">写作风格</label><div className="choice-row">{([['formal', '正式稳妥'], ['concise', '简洁直接'], ['explanatory', '解释充分']] as const).map(([key, label]) => <button key={key} className={`choice ${style === key ? 'selected' : ''}`} onClick={() => setStyle(key)}>{label}</button>)}</div><label className="label section">重点强调</label><div className="choice-row">{options.map((item) => <button key={item} className={`choice ${emphasis.includes(item) ? 'selected' : ''}`} onClick={() => setEmphasis(emphasis.includes(item) ? emphasis.filter((x) => x !== item) : [...emphasis, item])}>{item}</button>)}</div><label className="label section">特殊情况说明（可选）</label><textarea className="field" rows={4} value={special} onChange={(e) => setSpecial(e.target.value)} placeholder="例如：单人旅行、多国行程、由他人资助"/><div className="notice blue section"><Info size={16}/><span>只会使用你填写的事实，不会自动虚构资金、学校或返程理由。</span></div><button className="btn btn-primary" style={{ marginTop: 16 }} onClick={generate} disabled={loading}>{loading ? <><RefreshCw size={16} className="spin"/>正在生成…</> : <><Sparkles size={16}/>生成双语解释信</>}</button></div><div className="card"><div className="section-title"><div><h2 style={{ fontSize: 18 }}>文书预览</h2><span className="muted">可编辑 · {state.coverLetter.generated ? '已生成' : '尚未生成'}</span></div>{state.coverLetter.generated && <button className="small-btn" onClick={download}><Download size={14}/>下载Word</button>}</div>{state.coverLetter.generated ? <><div className="filter-row"><button className={`filter ${lang === 'en' ? 'active' : ''}`} onClick={() => setLang('en')}>English</button><button className={`filter ${lang === 'zh' ? 'active' : ''}`} onClick={() => setLang('zh')}>中文</button></div><textarea className="field" style={{ minHeight: 420, lineHeight: 1.7 }} value={state.coverLetter[lang]} onChange={(e) => updateText(e.target.value)}/><p className="footer-note">生成内容必须由申请人逐句核对，尤其是日期、资金和返程理由。</p></> : <div className="empty"><FileText size={35}/><p>填写左侧设置后生成你的双语解释信。</p></div>}</div></div></> }

function ConsistencyPage() { const { state, dispatch } = useStore(); const navigate = useNavigate(); const report = state.report; const run = () => dispatch({ type: 'SET_REPORT', report: runConsistencyCheck(state) }); const severityIcon = (s: Severity) => s === 'error' ? <AlertCircle size={18}/> : s === 'warning' ? <AlertCircle size={18}/> : s === 'pass' ? <CheckCircle2 size={18}/> : <Info size={18}/>; const go = (target: string) => navigate(target); return <><PageHead eyebrow="Step 5 · Consistency" title="一致性检查" description="点击一次，检查当前档案、上传字段、行程单和解释信是否互相支持。" actions={<button className="btn btn-primary" onClick={run}><ShieldCheck size={16}/>检查全部材料</button>}/>{!report ? <div className="card empty"><ShieldCheck size={46} color="var(--coral)"/><h2>准备好做一次递交前体检了吗？</h2><p>系统会检查日期、城市、住宿、保险、主申国和文书内容。</p><button className="btn btn-primary" onClick={run}>开始检查 <ArrowRight size={16}/></button></div> : <><div className="report-hero"><div className="score">{report.coverage}%</div><div><h2 style={{ margin: '0 0 8px' }}>材料覆盖率</h2><p className="muted" style={{ margin: 0 }}>已核验 {report.passedRules.length} 项 · {report.issues.filter((i) => i.severity === 'error').length} 项必须修复 · {report.uncheckedRules.length} 项无法自动检查</p><button className="small-btn" style={{ marginTop: 13 }} onClick={run}><RefreshCw size={13}/>重新检查</button></div></div><div className="grid-4 section"><div className="stat"><strong style={{ color: 'var(--red)' }}>{report.issues.filter((i) => i.severity === 'error').length}</strong><span>必须修复</span></div><div className="stat"><strong style={{ color: 'var(--yellow)' }}>{report.issues.filter((i) => i.severity === 'warning').length}</strong><span>建议确认</span></div><div className="stat"><strong style={{ color: 'var(--blue)' }}>{report.uncheckedRules.length}</strong><span>无法检查</span></div><div className="stat"><strong style={{ color: 'var(--green)' }}>{report.passedRules.length}</strong><span>已通过</span></div></div><section className="section"><div className="section-title"><h2>检查结果</h2><span className="muted">{new Date(report.createdAt).toLocaleString('zh-CN')}</span></div><div className="timeline">{report.issues.map((item) => <div className={`issue ${item.severity}`} key={item.id}><div style={{ display: 'flex', gap: 9, alignItems: 'center' }}><span className={`badge ${item.severity === 'error' ? 'red' : item.severity === 'warning' ? 'yellow' : 'blue'}`}>{severityIcon(item.severity)}{item.severity === 'error' ? '必须修复' : item.severity === 'warning' ? '建议确认' : '无法检查'}</span><h3>{item.title}</h3></div><p><strong>发现：</strong>{item.found}</p><p><strong>原因：</strong>{item.reason}</p><p><strong>建议：</strong>{item.action}</p><div className="issue-foot"><span className="muted">依据：{item.source}</span><button className="small-btn" onClick={() => go(item.target)}>前往修复 <ArrowRight size={13}/></button></div></div>)}</div>{!report.issues.length && <div className="notice green"><CheckCircle2 size={17}/><span>暂未发现可自动检查的冲突，但仍请人工核对原件和官方最新要求。</span></div>}</section><div className="section card"><div className="section-title"><h2>已通过与无法检查</h2><span className="badge blue">可继续人工确认</span></div><div className="grid-2"><div><span className="label">已通过规则</span>{report.passedRules.map((x) => <p key={x} style={{ fontSize: 13 }}><Check size={14} color="var(--green)" style={{ verticalAlign: 'middle' }}/> {x}</p>)}</div><div><span className="label">无法自动检查</span>{report.uncheckedRules.map((x) => <p key={x} style={{ fontSize: 13 }}><Info size={14} color="var(--blue)" style={{ verticalAlign: 'middle' }}/> {x}</p>)}</div></div></div></>}</> }

function PackagePage() { const { state } = useStore(); const profile = state.profile!; const reqs = requirementsFor(profile); const groups = ['online', 'onsite', 'both'] as const; const exportPackage = async () => { const zip = new JSZip(); const index = ['申根签证材料索引', `主申国：${countryLabels[profile.applicationCountry]}`, `递签地：${profile.submissionPlace === 'uk' ? '英国' : '中国大陆'}`, '', '请以官方最新要求为准。']; groups.forEach((channel) => { const folder = zip.folder(channel === 'online' ? '01_线上提交' : channel === 'onsite' ? '02_现场携带' : '03_两者都要'); reqs.filter((r) => r.channel === channel).forEach((r) => { const status = state.statuses[r.id] || 'todo'; folder?.file(`${r.name}.txt`, `${r.name}\n状态：${statusLabel[status]}\n递交方式：${channelLabel[r.channel]}\n官方依据：${r.source}\n`); index.push(`${r.name} | ${channelLabel[r.channel]} | ${statusLabel[status]}`) }) }); zip.folder('04_一致性检查报告')?.file('report.json', JSON.stringify(state.report || { message: '尚未检查' }, null, 2)); zip.file('材料索引.txt', index.join('\n')); const blob = await zip.generateAsync({ type: 'blob' }); saveBlob(blob, `Schengen_Material_Package_${profile.applicationCountry}.zip`, 'application/zip') }; return <><PageHead eyebrow="Step 6 · Package" title="材料包" description="按官方递交渠道整理，最后一步是确认状态与导出。" actions={<button className="btn btn-primary" onClick={exportPackage}><FileArchive size={16}/>一键打包下载</button>}/>{state.report?.issues.some((i) => i.severity === 'error') && <div className="notice red"><AlertCircle size={17}/><span>当前还有必须修复的问题。仍可以导出，但材料索引会保留风险提醒。</span></div>}<div className="grid-4 section"><div className="stat"><strong>{reqs.length}</strong><span>材料项目</span></div><div className="stat"><strong>{reqs.filter((r) => ['checked', 'uploaded', 'done'].includes(state.statuses[r.id])).length}</strong><span>已确认</span></div><div className="stat"><strong>{state.documents.length}</strong><span>上传文件</span></div><div className="stat"><strong>{state.report?.issues.filter((i) => i.severity === 'error').length || 0}</strong><span>待修复问题</span></div></div><div className="card section"><div className="section-title"><h2>材料目录</h2><span className="muted">导出后仍建议人工核对原件</span></div>{groups.map((channel) => <div key={channel}><h3 className="group-title">{channelLabel[channel]}</h3>{reqs.filter((r) => r.channel === channel).map((r) => <div className="package-row" key={r.id}><span className="check-circle">{['checked', 'uploaded', 'done'].includes(state.statuses[r.id]) ? <Check size={14}/> : <Info size={14}/>}</span><span><strong>{r.name}</strong><small className="muted" style={{ display: 'block', marginTop: 3 }}>{r.originals}</small></span><span className={`badge ${state.statuses[r.id] === 'uploaded' ? 'green' : state.statuses[r.id] ? 'yellow' : 'gray'}`}>{statusLabel[state.statuses[r.id] || 'todo']}</span></div>)}</div>)}<div className="notice blue" style={{ marginTop: 18 }}><LockKeyhole size={16}/><span>材料将按递交渠道整理并生成索引。</span></div></div></> }

function autoSchedule(input: CityStay[], start: string, end: string, mainCountry: string): CityStay[] {
  const selected = input.filter((city) => city.city.trim())
  if (!selected.length || !start || !end) return selected
  const startMs = new Date(`${start}T00:00:00`).getTime()
  const endMs = new Date(`${end}T00:00:00`).getTime()
  const totalNights = Math.max(1, Math.round((endMs - startMs) / 86400000))
  const base = Math.max(1, Math.floor(totalNights / selected.length))
  let remainder = Math.max(0, totalNights - base * selected.length)
  let cursor = startMs
  return selected.map((city, index) => {
    const extra = remainder > 0 && (city.country === mainCountry || index === selected.length - 1) ? 1 : 0
    if (extra) remainder -= 1
    const nights = base + extra
    const checkin = new Date(cursor).toISOString().slice(0, 10)
    const checkoutMs = index === selected.length - 1 ? endMs : cursor + nights * 86400000
    const checkout = new Date(checkoutMs).toISOString().slice(0, 10)
    cursor = checkoutMs
    return { ...city, checkin, checkout, hotel: city.hotel || `${city.city}住宿候选` }
  })
}

